head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[wframe > E > onwframeload]<br/>컴포넌트에 연결된 WebSquare XML 페이지가 렌더링된 후에 발생합니다.",
    "validation" : [    
        "컴포넌트에 연결된 WebSquare XML 페이지가 렌더링된 후에 발생합니다.",
        "WFrame 컴포넌트의 내부 영역이 모두 렌더링된 후 onwframeload 이벤트가 발생합니다.",
        "WebSquare XML 페이지가 setSrc(), msaLoad() 메소드로 제거되고 다시 연결되는 과정에서 onbeforewframeunload -> onwframeunload -> onwframeload 이벤트가 순서대로 발생합니다.",
        "WFrame 컴포넌트가 최초로 렌더링될때는 onwframeload 이벤트만 발생합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        src : "/sample/common_link/wframe_link_1.xml",
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onbeforewframeunload", "onwframeunload", "onwframeload"]);

    let grp_comp = $c.gcm.getTestGroup();    
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:wframe ' + strNameSpace + ' ' + cList + ' ' + eList + ' style="width:500px; height:300px; background-color:silver;" id=""></w2:wframe>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "wframe",
        strTarget,
        grp_comp
    );    
}



scwin.btn_setSrc_onclick = async function (e) {
    let src = par_src.getText();

    await target1.setSrc(src);    
}



scwin.target1_onbeforewframeunload = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onbeforewframeunload=====");
}



scwin.target1_onwframeunload = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onwframeunload=====");
}



scwin.target1_onwframeload = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onwframeload=====");
}
